package com.campusnova.controller; import com.campusnova.dto.ChatRequest; import com.campusnova.model.*; import com.campusnova.repository.*; import com.campusnova.service.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api") public class PublicController { private final ChatbotService chatbot; private final FaqService faq; private final AnnouncementRepository announcements; private final ChatHistoryRepository history; public PublicController(ChatbotService c,FaqService f,AnnouncementRepository a,ChatHistoryRepository h){chatbot=c;faq=f;announcements=a;history=h;} @PostMapping("/chat") public Map<String,Object> chat(@RequestBody ChatRequest r){return chatbot.respond(r);}@GetMapping("/faqs") public List<Faq> faqs(@RequestParam(required=false)String q){return faq.all(q);}@GetMapping("/announcements") public List<Announcement> announcements(){return announcements.findAll();}@GetMapping("/history/{session}") public List<ChatHistory> history(@PathVariable String session){return history.findTop20BySessionIdOrderByCreatedAtDesc(session);} }
